import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/getting-started/overview.md","filePath":"openshield-xdp/getting-started/overview.md","lastUpdated":null}'),s={name:"openshield-xdp/getting-started/overview.md"};function i(n,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>OpenShield-XDP is an XDP-native DDoS mitigation engine that inspects and drops attack traffic inside the NIC driver — before the kernel allocates an skb, before iptables runs.</p><h2 id="why-xdp" tabindex="-1">Why XDP? <a class="header-anchor" href="#why-xdp" aria-label="Permalink to &quot;Why XDP?&quot;">​</a></h2><p>XDP operates at the earliest point in the Linux stack: directly on DMA packet buffers, with zero per-packet allocation, zero sk_buff overhead, and zero context switches. A single core processes 10M+ PPS.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Game servers under UDP reflection floods. Web servers under SYN floods. DNS resolvers under amplification attacks. Any public-facing service at risk of L3/L4 DDoS.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>42 detection vectors across L2–L7. Suspicion scoring with an established-connection exemption and per-port threshold overrides, attack mode with a rotation-proof per-port cap, a behavior engine that auto-bans lookalike bot clusters, rate-based SYN-flood mitigation, subnet bans, Bloom filter for fast whitelist lookups, freplace hot-patching for modular BPF logic. 7-screen TUI dashboard with braille-resolution charts and config editor. Optional JSON metrics API. Webhook alerts (Discord/Slack).</p><p>New here? Start with the <a href="/pingless-studios-docs/openshield-xdp/user-guide/">User Guide for server owners</a> — plain-language setup and tuning.</p><h2 id="what-it-doesn-t-do" tabindex="-1">What it doesn&#39;t do <a class="header-anchor" href="#what-it-doesn-t-do" aria-label="Permalink to &quot;What it doesn&#39;t do&quot;">​</a></h2><p>Doesn&#39;t replace iptables (different layer). Doesn&#39;t intercept TLS (L2–L4 only). Isn&#39;t a WAF.</p><h2 id="kernel-requirements" tabindex="-1">Kernel requirements <a class="header-anchor" href="#kernel-requirements" aria-label="Permalink to &quot;Kernel requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Minimum</th><th>Recommended</th></tr></thead><tbody><tr><td>Linux kernel</td><td>5.15</td><td>6.10+</td></tr><tr><td>BTF support</td><td><code>CONFIG_DEBUG_INFO_BTF=y</code></td><td><code>CONFIG_DEBUG_INFO_BTF=y</code></td></tr><tr><td>freplace</td><td>5.15+</td><td>6.10+ (full feature set)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Kernel feature gates</p><p>Some features require newer kernels:</p><ul><li><strong>Bloom filter map</strong> — kernel 5.16+</li><li><strong>freplace (BPF hot-patching)</strong> — kernel 5.15+, but stable on 6.10+</li><li><strong>BPF timers</strong> (connection tracking TTL) — kernel 5.15+</li><li><strong>XDP generic/skb modes</strong> — any kernel with XDP support</li></ul><p>OpenShield-XDP auto-detects available kernel features at load time and disables unsupported features gracefully. Run <code>openshield status</code> to see which features are active.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p><a href="/pingless-studios-docs/openshield-xdp/getting-started/installation">Installation</a> · <a href="/pingless-studios-docs/openshield-xdp/getting-started/quick-start">Quick Start</a></p>',16)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
